    // el Header de cliente con sesion iniciada
    import React from 'react';
    //imagenes
    import logo from '../assets/Logo_GO2.png';
import carrito from '../assets/icono_carrito.png'; 
import perfil from '../assets/icono_usuario.png'; 
// Íconos Rosas (Versión Activa)
import carrito_rosa from '../assets/icono_carrito2.png'; 
import perfil_rosa from '../assets/icono_usuario2.png';

    import { Link, useLocation } from 'react-router-dom';

    import './header_c.css';

    const Header = () => {
    const location = useLocation();

    return (
        <header className="header-cliente">
        <div className="header-container_c">
            <div className="logo">
            <Link to="/"> 
                <img src={logo} alt="Logo Gurama Online" />            
            </Link>
            </div>

            <nav className="menu">
            <ul>
                <li>
                    <Link 
                        to="/" 
                        className={location.pathname === '/' || location.pathname === '/cliente' ? 'activo' : ''}
                    >
                        Inicio
                    </Link>
                </li>
                <li>
                    <Link 
                        to="/catalogo_c" 
                        className={location.pathname.startsWith('/catalogo_c') ? 'activo' : ''}
                    >
                        Catálogo
                    </Link>
                </li>
                <li>
                    <Link to="/pedidos-personalizados">Pedido personalizado</Link>
                </li>
                <li>
                    <Link to="#"> 
                    Cerrar sesión
                    </Link>
                </li>
            </ul>
            </nav>

            <div className="iconos">
                <Link to="/carrito">
                    <img 
                        src={isCarritoActive ? carrito_rosa : carrito_negro}
                        alt="icono carrito" 
                    />
                </Link>
                <Link to="/perfil">
                    <img 
                        src={isPerfilActive ? perfil_rosa : perfil_negro}
                        alt="icono perfil" 
                    />
                </Link>
            </div>
        </div>
    </header>
    );
    };

    export default Header;
